public String format(List<RevCommit> squashedCommits, Ref target) {StringBuilder sb = new StringBuilder();sb.append("Squashed commit of the following:
"); for (RevCommit c : squashedCommits) {sb.append("
commit "); sb.append(c.getName());sb.append("
"); sb.append(toString(c.getAuthorIdent()));sb.append("
	"); sb.append(c.getShortMessage());sb.append("
"); }return sb.toString();}

