public override string ToString(){var b = new StringBuilder();b.Append("initial state: ").Append(m_initial).Append(<MASKED>);for (int i = 0; i < _size; i++){b.Append("state " + i);if (m_accept[i]){b.Append(" [accept]:
");}else{b.Append(" [reject]:
");}for (int j = 0; j < _points.Length; j++){int k = m_transitions[i * _points.Length + j];if (k != -1){int min = _points[j];int max;if (j + 1 < _points.Length){max = (_points[j + 1] - 1);}else{max = _maxInterval;}b.Append(" ");Transition.AppendCharString(min, b);if (min != max){b.Append("-");Transition.AppendCharString(max, b);}b.Append(" -> ").Append(k).Append("
");}}}return b.ToString();}

